package com.aespejo.registrations.domain.entities;

import com.aespejo.registrations.domain.common.Auditable;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.OffsetDateTime;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/**
 * Organization-wide default values. It is a single-row table with {@code id} always set to 1. The id
 * is fixed by the code, not generated by the database.
 */
@Getter
@Setter
@NoArgsConstructor
@Entity
@Table(name = "Settings")
public class SystemSettings implements Auditable {

    /** Always 1: the table holds a single row. */
    @Id
    private int id = 1;

    private String organizationName;

    /** Text copied into the waiver of a new event when it is left blank. */
    private String defaultWaiverText;

    private int defaultReservationHours = 48;

    private int defaultPaymentToleranceCents;

    /** Global service fee. It sets the exact amount that every payment QR code must carry. */
    private int serviceFeeCents = 400;

    /** Money Sport credit per finished event, in cents. Default is USD 40. */
    private int moneySportAmountCents = 4000;

    /** Open-amount QR code used to charge the remaining balance when the athlete pays with virtual money. */
    private String genericQrPath;

    private OffsetDateTime updatedAt;
}
